import java.util.*;
public class Solution {
    static char[][] grid;
    static int rows, cols;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if(!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();
        // Simplified parsing for 2D array representation
        line = line.substring(1, line.length()-1);
        List<char[]> list = new ArrayList<>();
        int i = 0;
        while(i < line.length()) {
            if (line.charAt(i) == '[') {
                int j = line.indexOf(']', i);
                String row = line.substring(i+1, j);
                String[] cells = row.split(",");
                char[] r = new char[cells.length];
                for(int c=0; c<cells.length; c++) r[c] = cells[c].trim().replace("\"", "").charAt(0);
                list.add(r); i = j + 1;
            } else i++;
        }
        grid = list.toArray(new char[0][]);
        if(grid.length == 0) { System.out.println(0); return; }
        rows = grid.length; cols = grid[0].length;
        int count = 0;
        for (int r=0; r<rows; r++) for(int c=0; c<cols; c++) if(grid[r][c]=='1') { count++; dfs(r,c); }
        System.out.println(count);
    }
    static void dfs(int r, int c) {
        if (r<0 || r>=rows || c<0 || c>=cols || grid[r][c]=='0') return;
        grid[r][c] = '0'; dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
    }
}

