using namespace std;

void dfs(vector<vector<char>>& grid, int r, int c) {
    if (r < 0 || r >= (int)grid.size() || c < 0 || c >= (int)grid[0].size() || grid[r][c] != '1') return;
    grid[r][c] = '0';
    dfs(grid, r + 1, c);
    dfs(grid, r - 1, c);
    dfs(grid, r, c + 1);
    dfs(grid, r, c - 1);
}

vector<vector<char>> parseGrid(const string& line) {
    vector<vector<char>> grid;
    size_t start = line.find('[');
    size_t end = line.rfind(']');
    if (start == string::npos || end == string::npos) return grid;

    size_t i = start + 1;
    while (i < end) {
        while (i < end && line[i] != '[') i++;
        if (i >= end) break;
        size_t close = line.find(']', i);
        if (close == string::npos) break;
        string inner = line.substr(i + 1, close - i - 1);
        vector<char> row;
        bool inQuotes = false;
        for (char ch : inner) {
            if (ch == '"' || ch == '\'') inQuotes = !inQuotes;
            else if (inQuotes && (ch == '0' || ch == '1')) row.push_back(ch);
        }
        if (!row.empty()) grid.push_back(row);
        i = close + 1;
    }
    return grid;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    if (!getline(cin, line)) return 0;

    vector<vector<char>> grid = parseGrid(line);
    if (grid.empty() || grid[0].empty()) {
        cout << 0 << "\n";
        return 0;
    }

    int count = 0;
    for (int i = 0; i < (int)grid.size(); i++) {
        for (int j = 0; j < (int)grid[0].size(); j++) {
            if (grid[i][j] == '1') {
                count++;
                dfs(grid, i, j);
            }
        }
    }

    cout << count << "\n";
    return 0;
}

