public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String gridLine = sc.nextLine().trim();
        if (!sc.hasNextLine()) return;
        int sr = Integer.parseInt(sc.nextLine().trim());
        if (!sc.hasNextLine()) return;
        int scVal = Integer.parseInt(sc.nextLine().trim());
        if (!sc.hasNextLine()) return;
        int color = Integer.parseInt(sc.nextLine().trim());

        int[][] image = parse2DArray(gridLine);
        int oldColor = image[sr][scVal];
        if (oldColor != color) dfs(image, sr, scVal, oldColor, color);

        System.out.println(Arrays.deepToString(image));
    }

    private static void dfs(int[][] img, int r, int c, int o, int n) {
        if (r < 0 || r >= img.length || c < 0 || c >= img[0].length || img[r][c] != o) return;
        img[r][c] = n;
        dfs(img, r + 1, c, o, n);
        dfs(img, r - 1, c, o, n);
        dfs(img, r, c + 1, o, n);
        dfs(img, r, c - 1, o, n);
    }

    private static int[][] parse2DArray(String s) {
        s = s.substring(1, s.length() - 1);
        List<int[]> res = new ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            if (s.charAt(i) == '[') {
                int j = s.indexOf(']', i);
                String rowStr = s.substring(i + 1, j);
                String[] parts = rowStr.split(",");
                int[] row = new int[parts.length];
                for (int k = 0; k < parts.length; k++) row[k] = Integer.parseInt(parts[k].trim());
                res.add(row);
                i = j + 1;
            } else i++;
        }
        return res.toArray(new int[0][]);
    }
}

