import java.util.*;
import java.util.regex.*;

public class Solution {
    static int[] parent;

    static int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }

    static void unionSet(int i, int j) {
        int rootI = find(i), rootJ = find(j);
        if (rootI != rootJ) parent[rootI] = rootJ;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        StringBuilder sb = new StringBuilder();
        while (sc.hasNext()) {
            sb.append(sc.next()).append(" ");
        }
        String input = sb.toString();

        Matcher m = Pattern.compile("\\[\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\]").matcher(input);
        while (m.find()) {
            int u = Integer.parseInt(m.group(1));
            int v = Integer.parseInt(m.group(2));
            if (u < n && v < n) {
                unionSet(u, v);
            }
        }

        int lastBracket = input.lastIndexOf(']');
        String remainder = (lastBracket != -1) ? input.substring(lastBracket + 1).trim() : input.trim();
        Scanner remSc = new Scanner(remainder);
        if (remSc.hasNextInt()) {
            int src = remSc.nextInt();
            int dst = remSc.nextInt();
            System.out.println(find(src) == find(dst) ? "True" : "False");
        }
    }
}

