#define MAX_COURSES 2000
#define MAX_EDGES 10000

int head[MAX_COURSES], to[MAX_EDGES], nxt[MAX_EDGES], in_deg[MAX_COURSES];
int edgeCount = 0;

void addEdge(int u, int v) {
    to[edgeCount] = v;
    nxt[edgeCount] = head[u];
    head[u] = edgeCount++;
    in_deg[v]++;
}

int main() {
    int numCourses;
    if (scanf("%d", &numCourses) != 1) return 0;

    for (int i = 0; i < numCourses; i++) {
        head[i] = -1;
        in_deg[i] = 0;
    }

    char line[50000];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    if (strlen(line) <= 1) {
        if (!fgets(line, sizeof(line), stdin)) return 0;
    }

    char* p = line;
    while (*p) {
        if (*p == '[') {
            p++;
            while (*p == ' ') p++;
            if (*p == '[') continue;
            if (*p == '-' || (*p >= '0' && *p <= '9')) {
                int c = strtol(p, &p, 10);
                while (*p && *p != ',') p++;
                if (*p == ',') p++;
                int pre = strtol(p, &p, 10);
                addEdge(pre, c);
            }
        } else {
            p++;
        }
    }

    int q[MAX_COURSES];
    int q_h = 0, q_t = 0;
    for (int i = 0; i < numCourses; i++) {
        if (in_deg[i] == 0) q[q_t++] = i;
    }

    int count = 0;
    while (q_h < q_t) {
        int curr = q[q_h++];
        count++;
        for (int e = head[curr]; e != -1; e = nxt[e]) {
            int neighbor = to[e];
            in_deg[neighbor]--;
            if (in_deg[neighbor] == 0) q[q_t++] = neighbor;
        }
    }

    printf("%s\n", (count == numCourses) ? "True" : "False");
    return 0;
}

