    string rest, token;
    while (cin >> token) rest += token + " ";

    vector<vector<int>> adj(numCourses);
    vector<int> inDegree(numCourses, 0);

    regex re("\\[\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\]");
    smatch match;
    string::const_iterator searchStart(rest.cbegin());
    while (regex_search(searchStart, rest.cend(), match, re)) {
        int c = stoi(match[1]);
        int pre = stoi(match[2]);
        if (c < numCourses && pre < numCourses) {
            adj[pre].push_back(c);
            inDegree[c]++;
        }
        searchStart = match.suffix().first;
    }

    queue<int> q;
    for (int k = 0; k < numCourses; k++) {
        if (inDegree[k] == 0) q.push(k);
    }

    int completed = 0;
