        int curr = q.front();
        q.pop();
        completed++;
        for (int next : adj[curr]) {
            inDegree[next]--;
            if (inDegree[next] == 0) q.push(next);
        }
    }

    cout << (completed == numCourses ? "True" : "False") << "\n";
    return 0;
