import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String beginWord = sc.nextLine().trim();
        // Remove quotes if present
        if (beginWord.startsWith("\"") && beginWord.endsWith("\""))
            beginWord = beginWord.substring(1, beginWord.length() - 1);
        String endWord = sc.nextLine().trim();
        if (endWord.startsWith("\"") && endWord.endsWith("\""))
            endWord = endWord.substring(1, endWord.length() - 1);
        String listLine = sc.nextLine().trim();

        // Parse word list ["word1", "word2", ...]
        List<String> wordList = new ArrayList<>();
        listLine = listLine.substring(1, listLine.length() - 1); // remove []
        if (!listLine.isEmpty()) {
            for (String w : listLine.split(",")) {
                w = w.trim().replace("\"", "");
                if (!w.isEmpty()) wordList.add(w);
            }
        }

        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) { System.out.println(0); return; }

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);
        int level = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                char[] chars = word.toCharArray();
                for (int j = 0; j < chars.length; j++) {
                    char orig = chars[j];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == orig) continue;
                        chars[j] = c;
                        String next = new String(chars);
                        if (next.equals(endWord)) { System.out.println(level + 1); return; }
                        if (wordSet.contains(next) && !visited.contains(next)) {
                            visited.add(next);
                            queue.offer(next);
                        }
                    }
                    chars[j] = orig;
                }
            }
            level++;
        }
        System.out.println(0);
    }
}

