public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();

        int[][] heights = parseGrid(line);
        if (heights.length == 0 || heights[0].length == 0) {
            System.out.println("[]");
            return;
        }

        int m = heights.length;
        int n = heights[0].length;

        boolean[][] pacific = new boolean[m][n];
        boolean[][] atlantic = new boolean[m][n];

        Queue<int[]> pacQ = new LinkedList<>();
        Queue<int[]> atlQ = new LinkedList<>();

        for (int i = 0; i < m; i++) {
            pacific[i][0] = true;
            pacQ.offer(new int[]{i, 0});
            atlantic[i][n - 1] = true;
            atlQ.offer(new int[]{i, n - 1});
        }
        for (int j = 0; j < n; j++) {
            pacific[0][j] = true;
            pacQ.offer(new int[]{0, j});
            atlantic[m - 1][j] = true;
            atlQ.offer(new int[]{m - 1, j});
        }

        bfs(heights, pacQ, pacific);
        bfs(heights, atlQ, atlantic);

        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (pacific[i][j] && atlantic[i][j]) {
                    result.add(Arrays.asList(i, j));
                }
            }
        }

        System.out.print("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) System.out.print(", ");
            System.out.print("[" + result.get(i).get(0) + ", " + result.get(i).get(1) + "]");
        }
        System.out.println("]");
    }

    static void bfs(int[][] heights, Queue<int[]> q, boolean[][] visited) {
        int m = heights.length, n = heights[0].length;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int r = curr[0], c = curr[1];
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && heights[nr][nc] >= heights[r][c]) {
                    visited[nr][nc] = true;
                    q.offer(new int[]{nr, nc});
                }
            }
        }
    }

    static int[][] parseGrid(String line) {
        List<List<Integer>> rows = new ArrayList<>();
        int start = line.indexOf('[');
        int end = line.lastIndexOf(']');
        if (start == -1 || end == -1) return new int[0][0];

        int i = start + 1;
        while (i < end) {
            while (i < end && line.charAt(i) != '[') i++;
            if (i >= end) break;
            int close = line.indexOf(']', i);
            if (close == -1) break;
            String inner = line.substring(i + 1, close);
            List<Integer> row = new ArrayList<>();
            for (String part : inner.split(",")) {
                String s = part.trim();
                if (!s.isEmpty()) row.add(Integer.parseInt(s));
            }
            rows.add(row);
            i = close + 1;
        }

        int[][] grid = new int[rows.size()][];
        for (int r = 0; r < rows.size(); r++) {
            grid[r] = new int[rows.get(r).size()];
            for (int c = 0; c < rows.get(r).size(); c++) {
                grid[r][c] = rows.get(r).get(c);
            }
        }
        return grid;
    }
}

