import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();

        List<String> words = parseWords(line);
        if (words.isEmpty()) {
            System.out.println("");
            return;
        }

        Map<Character, Set<Character>> adj = new HashMap<>();
        Map<Character, Integer> inDegree = new HashMap<>();

        for (String w : words) {
            for (char c : w.toCharArray()) {
                adj.putIfAbsent(c, new HashSet<>());
                inDegree.putIfAbsent(c, 0);
            }
        }

        for (int i = 0; i < words.size() - 1; i++) {
            String w1 = words.get(i), w2 = words.get(i + 1);
            int minLen = Math.min(w1.length(), w2.length());
            if (w1.length() > w2.length() && w1.startsWith(w2)) {
                System.out.println("");
                return;
            }
            for (int j = 0; j < minLen; j++) {
                char c1 = w1.charAt(j), c2 = w2.charAt(j);
                if (c1 != c2) {
                    if (!adj.get(c1).contains(c2)) {
                        adj.get(c1).add(c2);
                        inDegree.put(c2, inDegree.get(c2) + 1);
                    }
                    break;
                }
            }
        }

        Queue<Character> q = new LinkedList<>();
        for (char c : inDegree.keySet()) {
            if (inDegree.get(c) == 0) q.offer(c);
        }

        StringBuilder sb = new StringBuilder();
        while (!q.isEmpty()) {
            char curr = q.poll();
            sb.append(curr);
            for (char next : adj.get(curr)) {
                inDegree.put(next, inDegree.get(next) - 1);
                if (inDegree.get(next) == 0) q.offer(next);
            }
        }

        if (sb.length() == inDegree.size()) {
            System.out.println(sb.toString());
        } else {
            System.out.println("");
        }
    }

    static List<String> parseWords(String line) {
        List<String> res = new ArrayList<>();
        int start = line.indexOf('[');
        int end = line.lastIndexOf(']');
        if (start == -1 || end == -1) return res;
        boolean inQuotes = false;
        StringBuilder sb = new StringBuilder();
        for (int i = start + 1; i < end; i++) {
            char ch = line.charAt(i);
            if (ch == '"' || ch == '\'') {
                if (inQuotes) {
                    res.add(sb.toString());
                    sb.setLength(0);
                    inQuotes = false;
                } else {
                    inQuotes = true;
                }
            } else if (inQuotes) {
                sb.append(ch);
            }
        }
        return res;
    }
}

