vector<vector<int>> parseGrid(const string& line) {
    vector<vector<int>> grid;
    size_t start = line.find('[');
    size_t end = line.rfind(']');
    if (start == string::npos || end == string::npos || start >= end) return grid;

    size_t i = start + 1;
    while (i < end) {
        while (i < end && line[i] != '[') i++;
        if (i >= end) break;
        size_t close = line.find(']', i);
        if (close == string::npos) break;
        string inner = line.substr(i + 1, close - i - 1);
        vector<int> row;
        stringstream ss(inner);
        string token;
        while (getline(ss, token, ',')) {
            size_t first = token.find_first_not_of(" \t\r\n");
            size_t last = token.find_last_not_of(" \t\r\n");
            if (first != string::npos) {
                row.push_back(stoi(token.substr(first, last - first + 1)));
            }
        }
        if (!row.empty()) grid.push_back(row);
        i = close + 1;
    }
    return grid;
}

