        Matcher m = Pattern.compile("\\[\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\]").matcher(input);
        while (m.find()) {
            int u = Integer.parseInt(m.group(1));
            int v = Integer.parseInt(m.group(2));
            if (!union(u, v)) {
                System.out.println("[" + u + ", " + v + "]");
                return;
            }
        }
    }
}

