using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        for (int i = 0; i <= n; i++) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    bool unite(int i, int j) {
        int rootI = find(i), rootJ = find(j);
        if (rootI != rootJ) {
            parent[rootI] = rootJ;
            return true;
        }
        return false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string token, input;
    while (cin >> token) input += token + " ";

    DSU dsu(2005);

    regex re("\\[\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\]");
    smatch match;
    string::const_iterator searchStart(input.cbegin());
    while (regex_search(searchStart, input.cend(), match, re)) {
        int u = stoi(match[1]);
        int v = stoi(match[2]);
        if (!dsu.unite(u, v)) {
            cout << "[" << u << ", " << v << "]\n";
            return 0;
        }
        searchStart = match.suffix().first;
    }
    return 0;
}

