            if (*p == '[') continue; // Outer bracket
            int current_cols = 0;
            while (*p && *p != ']') {
                if (*p >= '0' && *p <= '9') {
                    grid[rows][current_cols++] = strtol(p, &p, 10);
                } else p++;
            }
            if (current_cols > 0) {
                cols = current_cols;
                rows++;
            }
        } else p++;
    }

    if (rows == 0) { printf("0\n"); return 0; }

    memset(visited, 0, sizeof(visited));
    int max_area = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 1 && !visited[r][c]) {
                int area = dfs(r, c);
                if (area > max_area) max_area = area;
            }
        }
    }
    printf("%d\n", max_area);
