import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();

        int[][] grid = parseGrid(line);
        if (grid.length == 0 || grid[0].length == 0) {
            System.out.println(0);
            return;
        }

        int maxArea = 0;
        int m = grid.length, n = grid[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    maxArea = Math.max(maxArea, dfs(grid, i, j));
                }
            }
        }

        System.out.println(maxArea);
    }

    static int dfs(int[][] grid, int r, int c) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] != 1) return 0;
        grid[r][c] = 0;
        return 1 + dfs(grid, r + 1, c) + dfs(grid, r - 1, c) + dfs(grid, r, c + 1) + dfs(grid, r, c - 1);
    }

    static int[][] parseGrid(String line) {
        List<List<Integer>> rows = new ArrayList<>();
        int start = line.indexOf('[');
        int end = line.lastIndexOf(']');
        if (start == -1 || end == -1) return new int[0][0];

        int i = start + 1;
        while (i < end) {
            while (i < end && line.charAt(i) != '[') i++;
            if (i >= end) break;
            int close = line.indexOf(']', i);
            if (close == -1) break;
            String inner = line.substring(i + 1, close);
            List<Integer> row = new ArrayList<>();
            for (String part : inner.split(",")) {
                String s = part.trim();
                if (!s.isEmpty()) row.add(Integer.parseInt(s));
            }
            rows.add(row);
            i = close + 1;
        }

        int[][] grid = new int[rows.size()][];
        for (int r = 0; r < rows.size(); r++) {
            grid[r] = new int[rows.get(r).size()];
            for (int c = 0; c < rows.get(r).size(); c++) {
                grid[r][c] = rows.get(r).get(c);
            }
        }
        return grid;
    }
}

